import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])

    if k == n:
        res = ['0'] * n
        print(''.join(res))
        return

    pattern_len = k + 1
    left_len = (pattern_len - 1) // 2
    right_len = pattern_len // 2

    left_part = []
    for i in range(left_len):
        left_part.append(str(i % 2))

    right_part = []
    for i in range(right_len):
        right_part.append(str((i + 1) % 2))

    middle = '1' if left_part else '0'
    if left_part and right_part:
        if left_part[-1] == right_part[0]:
            middle = '0' if left_part[-1] == '1' else '1'
        else:
            middle = '1' if left_part[-1] == '1' else '0'
    elif left_part:
        middle = '0' if left_part[-1] == '1'
    elif right_part:
        middle = '1' if right_part[0] == '0'

    core = left_part + [middle] + right_part

    remaining = n - len(core)
    if remaining > 0:
        suffix = ['0'] * remaining
        if core:
            if core[-1] == '0':
                suffix = ['1'] * remaining
        core = core + suffix

    while len(core) < n:
        if core[-1] == '0':
            core.append('1')
        else:
            core.append('0')

    print(''.join(core[:n]))

if __name__ == "__main__":
    main()
